import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import API from '../api/axios';
import { ShieldAlert, Loader2 } from 'lucide-react';

export default function Login() {
  const navigate = useNavigate();
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // ব্যাকএন্ডে জিমেইল যাচাই ও লগইন
  const verifyAndLogin = async (email, name) => {
    try {
      setLoading(true);
      setError('');
      const res = await API.post('/auth/google-login', {
        email: email,
        name: name || email.split('@')[0]
      });

      if (res.data.success && res.data.token) {
        localStorage.setItem('admin_token', res.data.token);
        localStorage.setItem('admin_user', JSON.stringify(res.data.user));
        navigate('/dashboard');
      }
    } catch (err) {
      setError(err.response?.data?.error || 'এই জিমেইলটি অ্যাডমিন হিসেবে অনুমোদিত নয়!');
    } finally {
      setLoading(false);
    }
  };

  // গুগল পপআপ ট্রিগার (পিসি বা ফোনের জিমেইল সিলেক্টর)
  const handleGooglePopupLogin = () => {
    if (!window.google) {
      setError('Google SDK লোড হতে পারেনি। ইন্টারনেট কানেকশন চেক করে রিলোড দিন।');
      return;
    }

    try {
      const client = window.google.accounts.oauth2.initTokenClient({
        // গুগল ও-অথ ক্লায়েন্ট আইডি
        client_id: '892348234723-dummyclientid.apps.googleusercontent.com',
        scope: 'email profile openid',
        callback: async (tokenResponse) => {
          if (tokenResponse && tokenResponse.access_token) {
            try {
              // গুগল থেকে সিলেক্ট করা জিমেইল প্রোফাইল ডাটা সংগ্রহ
              const userInfo = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', {
                headers: { Authorization: `Bearer ${tokenResponse.access_token}` }
              }).then((res) => res.json());

              if (userInfo && userInfo.email) {
                verifyAndLogin(userInfo.email, userInfo.name);
              }
            } catch (e) {
              setError('গুগল অ্যাকাউন্ট তথ্য পাওয়া যায়নি!');
            }
          }
        },
      });

      client.requestAccessToken();
    } catch (err) {
      setError('গুগল পপআপ ওপেন করা সম্ভব হয়নি!');
    }
  };

  return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4 font-sans">
      <div className="bg-white rounded-3xl p-8 max-w-sm w-full shadow-2xl space-y-6 text-center">
        <div>
          <div className="w-16 h-16 bg-emerald-100 text-emerald-800 rounded-2xl flex items-center justify-center mx-auto mb-3 font-black text-2xl shadow-inner">
            CF
          </div>
          <h2 className="text-2xl font-black text-gray-900">CityFood Control</h2>
          <p className="text-xs text-gray-500 font-semibold mt-1">Authorized Gmail Sign-In</p>
        </div>

        {error && (
          <div className="p-3 bg-red-50 border border-red-200 text-red-700 text-xs rounded-xl flex items-center gap-2 font-bold text-left">
            <ShieldAlert className="w-4 h-4 flex-shrink-0 text-red-600" />
            <span>{error}</span>
          </div>
        )}

        <div className="pt-2">
          {/* একক ও আসল গুগল লগইন বাটন */}
          <button
            type="button"
            onClick={handleGooglePopupLogin}
            disabled={loading}
            className="w-full py-3.5 px-4 border border-gray-300 rounded-2xl font-bold text-xs text-gray-700 bg-white hover:bg-gray-50 shadow-sm transition-all flex items-center justify-center gap-3 cursor-pointer active:scale-95 disabled:opacity-60"
          >
            {loading ? (
              <Loader2 className="w-4 h-4 animate-spin text-emerald-600" />
            ) : (
              <svg className="w-4 h-4" viewBox="0 0 24 24">
                <path
                  fill="#4285F4"
                  d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
                />
                <path
                  fill="#34A853"
                  d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
                />
                <path
                  fill="#FBBC05"
                  d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.06H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.94l2.85-2.22.81-.63z"
                />
                <path
                  fill="#EA4335"
                  d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.06l3.66 2.84c.87-2.6 3.3-4.52 6.16-4.52z"
                />
              </svg>
            )}
            <span>{loading ? 'যাচাই করা হচ্ছে...' : 'Continue with Google'}</span>
          </button>
        </div>

        <div className="bg-gray-50 p-3 rounded-2xl border border-gray-100 text-[10px] text-gray-500 font-medium leading-relaxed">
          🔒 শুধুমাত্র <strong>tanvir.it009@gmail.com</strong> এবং ডাটাবেজে অনুমোদিত সাব-অ্যাডমিনরা প্রবেশ করতে পারবে।
        </div>
      </div>
    </div>
  );
}
